request.system:
You are designing a realistic event-level simulator for industrial equipment.

You are given:
1. A telemetry schema
2. Relevant manual context extracted from the equipment documentation

Your job is NOT to write code yet.
Your job is to design the simulator specification.

Return ONLY valid JSON with exactly this structure:

{
  "machine_type": "string",
  "machine_name": "string",
  "operation_types": [
    {
      "name": "string",
      "description": "string",
      "active_subsystems": ["string"]
    }
  ],
  "subsystems": [
    {
      "name": "string",
      "description": "string",
      "state_variables": ["string"]
    }
  ],
  "state_variables": [
    {
      "name": "string",
      "subsystem": "string",
      "type": "permanent_degradation|reversible_buildup|thermal|usage|other",
      "description": "string",
      "affects_fields": ["string"]
    }
  ],
  "usage_profiles": [
    {
      "name": "string",
      "description": "string",
      "operating_hours": "string",
      "relative_intensity": "low|medium|high",
      "operation_mix": {}
    }
  ],
  "field_generation_rules": [
    {
      "field_name": "string",
      "role": "control_input|measured_sensor|duration|outcome|metadata",
      "depends_on": ["string"],
      "generation_logic": "string"
    }
  ],
  "degradation_model": [
    {
      "state_variable": "string",
      "accumulates_from": "string",
      "restored_by": ["string"],
      "effects_on_fields": ["string"]
    }
  ],
  "maintenance_model": [
    {
      "event_type": "string",
      "trigger": "string",
      "effect_on_state": "string"
    }
  ],
  "failure_model": [
    {
      "failure_name": "string",
      "trigger_conditions": "string",
      "observable_effects": ["string"]
    }
  ],
  "event_timing_model": {
    "arrival_process": "string",
    "notes": "string"
  },
  "null_field_rules": [
    {
      "operation_type": "string",
      "fields_set_to_null": ["string"],
      "reason": "string"
    }
  ]
}

Requirements:
- Base everything only on the schema and manual context.
- Do not invent unsupported operation types or subsystems.
- Focus on realism for event-level telemetry simulation.
- If a field applies only to some operation types, capture that in null_field_rules.
- Return JSON only.

responses.text:
```json
{
  "machine_type": "Booster Pump Skid",
  "machine_name": "TP-200 Booster Pump Skid",
  "operation_types": [
    {
      "name": "normal_boosting",
      "description": "Standard pressurized water boosting cycle with pump P1 running, filter F1 in clean or mildly loaded state, inlet and discharge pressures within permitted ranges.",
      "active_subsystems": ["filter_f1", "pump_p1", "motor_p1", "monitoring_system"]
    },
    {
      "name": "degraded_filter_boosting",
      "description": "Boosting cycle where filter F1 is partially or heavily clogged, causing elevated filter_dp, reduced inlet pressure, and potential cavitation risk.",
      "active_subsystems": ["filter_f1", "pump_p1", "motor_p1", "monitoring_system"]
    },
    {
      "name": "degraded_pump_boosting",
      "description": "Boosting cycle where pump P1 impeller and wear ring are worn, causing reduced discharge pressure and elevated motor current at a given flow rate.",
      "active_subsystems": ["filter_f1", "pump_p1", "motor_p1", "monitoring_system"]
    },
    {
      "name": "cavitation_event",
      "description": "Boosting cycle where inlet pressure drops below 0.5 bar (due to clogged filter or low supply pressure), causing pump cavitation with elevated vibration and accelerated impeller wear.",
      "active_subsystems": ["filter_f1", "pump_p1", "motor_p1", "monitoring_system"]
    },
    {
      "name": "pump_stopped",
      "description": "Pump P1 is not running; skid is idle. No flow, no boosting. May occur after a fault alarm or during a maintenance window.",
      "active_subsystems": ["monitoring_system"]
    }
  ],
  "subsystems": [
    {
      "name": "filter_f1",
      "description": "20-micron pleated cartridge inlet filter upstream of pump P1. Removes particles from supply water. Differential pressure across the cartridge rises as particles accumulate.",
      "state_variables": ["filter_loading", "filter_dp_base"]
    },
    {
      "name": "pump_p1",
      "description": "Single-stage centrifugal booster pump driven by a 1.5 kW motor. Impeller and wear ring degrade over operating hours, lowering discharge pressure and raising motor current at a given flow.",
      "state_variables": ["impeller_wear", "cavitation_exposure_hours"]
    },
    {
      "name": "motor_p1",
      "description": "1.5 kW electric motor driving pump P1. Motor temperature rises with load and ambient conditions. Current draw increases with impeller wear.",
      "state_variables": ["motor_thermal_state"]
    },
    {
      "name": "monitoring_system",
      "description": "Onboard data acquisition system sampling all sensor channels every 10 seconds and evaluating warning and alarm thresholds.",
      "state_variables": []
    }
  ],
  "state_variables": [
    {
      "name": "filter_loading",
      "subsystem": "filter_f1",
      "type": "reversible_buildup",
      "description": "Cumulative particle load on the F1 cartridge expressed as a fraction from 0 (clean) to 1 (fully blocked). Drives filter_dp upward. Reset to 0 on cartridge replacement. Accumulation rate increases under high particle load conditions.",
      "affects_fields": ["filter_dp", "filter_f1_state", "inlet_pressure", "w21_filter_clogging_triggered", "a22_filter_blocked_triggered", "active_warning_codes", "active_alarm_codes", "cavitation_detected", "cavitation_risk"]
    },
    {
      "name": "filter_dp_base",
      "subsystem": "filter_f1",
      "type": "reversible_buildup",
      "description": "Baseline differential pressure across F1 at rated flow, derived from filter_loading. Starts at 0.10 bar for a clean cartridge and rises toward and beyond 0.80 bar as loading increases.",
      "affects_fields": ["filter_dp", "filter_f1_state", "inlet_pressure"]
    },
    {
      "name": "impeller_wear",
      "subsystem": "pump_p1",
      "type": "permanent_degradation",
      "description": "Cumulative wear on the impeller and wear ring expressed as a fraction from 0 (new) to 1 (end-of-life at ~20000 hours rated, or ~10000 hours with sustained cavitation). Lowers discharge pressure and raises motor current at a given flow.",
      "affects_fields": ["discharge_pressure", "motor_current", "pump_performance_state", "w31_pump_performance_low_triggered", "a32_pump_worn_triggered", "a33_motor_current_high_triggered", "active_warning_codes", "active_alarm_codes", "pump_p1_state"]
    },
    {
      "name": "cavitation_exposure_hours",
      "subsystem": "pump_p1",
      "type": "usage",
      "description": "Cumulative hours of operation with inlet pressure below 0.5 bar. Accelerates impeller_wear at double the normal rate. Also elevates vibration_rms during active cavitation.",
      "affects_fields": ["impeller_wear", "vibration_rms", "cavitation_detected", "cavitation_risk", "w35_vibration_warning_triggered", "a36_vibration_alarm_triggered"]
    },
    {
      "name": "motor_thermal_state",
      "subsystem": "motor_p1",
      "type": "thermal",
      "description": "Current thermal state of the motor expressed as temperature in degC. Rises with load (motor current) and cycle duration; decays toward ambient when pump is stopped. Triggers A-34 above 95 degC.",
      "affects_fields": ["motor_temperature", "a34_motor_temperature_high_triggered", "active_alarm_codes", "pump_p1_state"]
    }
  ],
  "usage_profiles": [
    {
      "name": "light_duty",
      "description": "Low-demand building with short boosting cycles and long idle periods. Water quality is good, particle load is low. Filter life approaches 3000 hours.",
      "operating_hours": "4 to 8 hours per day",
      "relative_intensity": "low",
      "operation_mix": {
        "normal_boosting": 0.90,
        "degraded_filter_boosting": 0.08,
        "degraded_pump_boosting": 0.02,
        "cavitation_event": 0.00,
        "pump_stopped": 0.00
      }
    },
    {
      "name": "standard_duty",
      "description": "Typical building with moderate continuous demand. Normal water quality. Filter replaced on schedule at 2000 hours. Pump overhauled at 20000 hours.",
      "operating_hours": "12 to 18 hours per day",
      "relative_intensity": "medium",
      "operation_mix": {
        "normal_boosting": 0.75,
        "degraded_filter_boosting": 0.15,
        "degraded_pump_boosting": 0.07,
        "cavitation_event": 0.02,
        "pump_stopped": 0.01
      }
    },
    {
      "name": "heavy_duty",
      "description": "High-demand building running near continuous duty. Elevated particle load (e.g., post mains repair) shortens filter life to ~500 hours. Pump wear is accelerated by frequent cavitation events.",
      "operating_hours": "20 to 24 hours per day",
      "relative_intensity": "high",
      "operation_mix": {
        "normal_boosting": 0.50,
        "degraded_filter_boosting": 0.25,
        "degraded_pump_boosting": 0.12,
        "cavitation_event": 0.10,
        "pump_stopped": 0.03
      }
    }
  ],
  "field_generation_rules": [
    {
      "field_name": "event_start_time",
      "role": "metadata",
      "depends_on": ["previous_event_end_time", "arrival_process"],
      "generation_logic": "Set to the UTC timestamp when the boosting cycle begins. Derived from the inter-arrival process. For continuous duty profiles, gap between events is near zero; for light duty, gaps of minutes to hours are inserted."
    },
    {
      "field_name": "event_end_time",
      "role": "metadata",
      "depends_on": ["event_start_time", "cycle_duration"],
      "generation_logic": "event_start_time + cycle_duration seconds, expressed as UTC timestamp."
    },
    {
      "field_name": "cycle_duration",
      "role": "duration",
      "depends_on": ["usage_profile", "operation_type"],
      "generation_logic": "Sampled from a log-normal distribution. Light duty: mean ~600s, heavy duty: mean ~14400s. Capped at 86400s. Pump_stopped events use short durations (10-300s)."
    },
    {
      "field_name": "event_duration",
      "role": "duration",
      "depends_on": ["cycle_duration"],
      "generation_logic": "Equal to cycle_duration. Both fields represent the same elapsed time from start to end of the boosting cycle."
    },
    {
      "field_name": "sample_interval",
      "role": "control_input",
      "depends_on": [],
      "generation_logic": "Fixed constant: always 10 seconds as specified in the manual."
    },
    {
      "field_name": "reporting_interval",
      "role": "control_input",
      "depends_on": [],
      "generation_logic": "Fixed constant: always 10 seconds as specified in the manual."
    },
    {
      "field_name": "pump_p1_running",
      "role": "control_input",
      "depends_on": ["operation_type"],
      "generation_logic": "True for all operation types except pump_stopped, where it is False."
    },
    {
      "field_name": "water_temperature",
      "role": "control_input",
      "depends_on": ["usage_profile"],
      "generation_logic": "Sampled from a uniform distribution between 5 and 35 degC. Seasonal variation can be applied: winter 5-15 degC, summer 18-35 degC. Slightly affects motor_temperature baseline."
    },
    {
      "field_name": "flow_rate",
      "role": "measured_sensor",
      "depends_on": ["operation_type", "usage_profile"],
      "generation_logic": "Sampled from a normal distribution centered on 6.0 m3/h (rated) with std ~0.8 m3/h, clipped to 2.0-8.0 m3/h. During degraded_filter_boosting with high filter_dp, flow may be slightly reduced (0.5-1.0 m3/h below nominal) due to increased restriction."
    },
    {
      "field_name": "inlet_pressure",
      "role": "measured_sensor",
      "depends_on": ["filter_loading", "filter_dp_base", "flow_rate"],
      "generation_logic": "Base inlet pressure drawn from normal distribution centered on 1.5 bar (std 0.2 bar). Subtract filter_dp_base scaled by (flow_rate/6.0)^2 to model filter restriction effect on inlet pressure. If result falls below 0.5 bar, cavitation conditions apply. Clipped to 0.0-3.0 bar."
    },
    {
      "field_name": "filter_dp",
      "role": "measured_sensor",
      "depends_on": ["filter_loading", "filter_dp_base", "flow_rate"],
      "generation_logic": "filter_dp = filter_dp_base * (flow_rate/6.0)^2. filter_dp_base starts at 0.10 bar for a clean cartridge and increases with filter_loading up to >0.80 bar at full block. Add small Gaussian noise (std 0.005 bar)."
    },
    {
      "field_name": "discharge_pressure",
      "role": "measured_sensor",
      "depends_on": ["impeller_wear", "flow_rate", "inlet_pressure"],
      "generation_logic": "New pump at rated flow: 4.5 bar. Discharge pressure decreases linearly with impeller_wear: at wear=1.0 (end of life), discharge_pressure at rated flow drops to ~3.2 bar. Also decreases with flow above rated (pump curve). Add Gaussian noise (std 0.05 bar). Clipped to 0.0-6.0 bar."
    },
    {
      "field_name": "motor_current",
      "role": "measured_sensor",
      "depends_on": ["impeller_wear", "flow_rate"],
      "generation_logic": "Nominal at rated flow: 3.2 A. Increases with impeller_wear (up to ~5.5 A at end-of-life wear) and with flow_rate above rated. Add Gaussian noise (std 0.05 A). Clipped to 0.0-10.0 A."
    },
    {
      "field_name": "motor_temperature",
      "role": "measured_sensor",
      "depends_on": ["motor_thermal_state", "motor_current", "cycle_duration", "water_temperature"],
      "generation_logic": "Modeled as a first-order thermal system. Steady-state temperature = ambient_base + k * motor_current^2. Ambient base ~25 degC + 0.5 * water_temperature. k calibrated so nominal current (3.2 A) yields ~55 degC steady state. Rises toward steady state with time constant ~1800s. Add Gaussian noise (std 0.5 degC). Clipped to 0-120 degC."
    },
    {
      "field_name": "vibration_rms",
      "role": "measured_sensor",
      "depends_on": ["impeller_wear", "cavitation_exposure_hours", "inlet_pressure", "flow_rate"],
      "generation_logic": "Baseline vibration: 1.0 mm/s for a new pump at rated flow. Increases with impeller_wear (up to ~3.5 mm/s at end-of-life). During active cavitation (inlet_pressure < 0.5 bar), add cavitation spike of 3.0-8.0 mm/s drawn from uniform distribution. Add Gaussian noise (std 0.1 mm/s). Clipped to 0.0-20.0 mm/s."
    },
    {
      "field_name": "cavitation_detected",
      "role": "outcome",
      "depends_on": ["inlet_pressure"],
      "generation_logic": "True if inlet_pressure fell below 0.5 bar at any point during the cycle. Determined by checking the minimum inlet_pressure value simulated across the cycle duration."
    },
    {
      "field_name": "cavitation_risk",
      "role": "outcome",
      "depends_on": ["inlet_pressure"],
      "generation_logic": "True if inlet_pressure fell below 0.5 bar at any point during the cycle. Equivalent to cavitation_detected; both flags are set together."
    },
    {
      "field_name": "filter_f1_state",
      "role": "outcome",
      "depends_on": ["filter_dp"],
      "generation_logic": "Derived from filter_dp: 'clean' if filter_dp <= 0.60 bar; 'clogging' if 0.60 < filter_dp <= 0.80 bar; 'blocked' if filter_dp > 0.80 bar."
    },
    {
      "field_name": "pump_performance_state",
      "role": "outcome",
      "depends_on": ["discharge_pressure", "flow_rate"],
      "generation_logic": "Evaluated at rated flow (6.0 m3/h): 'normal' if discharge_pressure >= 3.8 bar; 'performance_low' if 3.5 <= discharge_pressure < 3.8 bar; 'worn' if discharge_pressure < 3.5 bar."
    },
    {
      "field_name": "pump_p1_state",
      "role": "outcome",
      "depends_on": ["pump_p1_running", "active_alarm_codes"],
      "generation_logic": "If pump_p1_running is False: 'stopped'. If any of A-32, A-33, A-34, A-36 are active: 'fault'. Otherwise: 'running'."
    },
    {
      "field_name": "w21_filter_clogging_triggered",
      "role": "outcome",
      "depends_on": ["filter_dp"],
      "generation_logic": "True if filter_dp exceeded 0.60 bar at any point during the cycle."
    },
    {
      "field_name": "a22_filter_blocked_triggered",
      "role": "outcome",
      "depends_on": ["filter_dp"],
      "generation_logic": "True if filter_dp exceeded 0.80 bar at any point during the cycle."
    },
    {
      "field_name": "w31_pump_performance_low_triggered",
      "role": "outcome",
      "depends_on": ["discharge_pressure", "flow_rate"],
      "generation_logic": "True if discharge_pressure fell below 3.8 bar when flow_rate was at or near rated flow (5.5-6.5 m3/h) at any point during the cycle."
    },
    {
      "field_name": "a32_pump_worn_triggered",
      "role": "outcome",
      "depends_on": ["discharge_pressure", "flow_rate"],
      "generation_logic": "True if discharge_pressure fell below 3.5 bar when flow_rate was at or near rated flow (5.5-6.5 m3/h) at any point during the cycle."
    },
    {
      "field_name": "a33_motor_current_high_triggered",
      "role": "outcome",
      "depends_on": ["motor_current"],
      "generation_logic": "True if motor_current exceeded 4.5 A at any point during the cycle."
    },
    {
      "field_name": "a34_motor_temperature_high_triggered",
      "role": "outcome",
      "depends_on": ["motor_temperature"],
      "generation_logic": "True if motor_temperature exceeded 95 degC at any point during the cycle."
    },
    {
      "field_name": "w35_vibration_warning_triggered",
      "role": "outcome",
      "depends_on": ["vibration_rms"],
      "generation_logic": "True if vibration_rms exceeded 4.5 mm/s at any point during the cycle."
    },
    {
      "field_name": "a36_vibration_alarm_triggered",
      "role": "outcome",
      "depends_on": ["vibration_rms"],
      "generation_logic": "True if vibration_rms exceeded 7.1 mm/s at any point during the cycle."
    },
    {
      "field_name": "active_warning_codes",
      "role": "outcome",
      "depends_on": ["w21_filter_clogging_triggered", "w31_pump_performance_low_triggered", "w35_vibration_warning_triggered"],
      "generation_logic": "Comma-separated list of warning codes triggered during the cycle. Include 'W-21' if w21_filter_clogging_triggered, 'W-31' if w31_pump_performance_low_triggered, 'W-35' if w35_vibration_warning_triggered. Empty string if none."
    },
    {
      "field_name": "active_alarm_codes",
      "role": "outcome",
      "depends_on": ["a22_filter_blocked_triggered", "a32_pump_worn_triggered", "a33_motor_current_high_triggered", "a34_motor_temperature_high_triggered", "a36_vibration_alarm_triggered"],
      "generation_logic": "Comma-separated list of alarm codes triggered during the cycle. Include 'A-22' if a22_filter_blocked_triggered, 'A-32' if a32_pump_worn_triggered, 'A-33' if a33_motor_current_high_triggered, 'A-34' if a34_motor_temperature_high_triggered, 'A-36' if a36_vibration_alarm_triggered. Empty string if none."
    }
  ],
  "degradation_model": [
    {
      "state_variable": "filter_loading",
      "accumulates_from": "Volume of water filtered (flow_rate * cycle_duration). Accumulation rate multiplied by a particle_load_factor: 1.0 for normal water quality, up to 4.0 for high particle load conditions (e.g., post mains repair). filter_loading increments by approximately (flow_rate * cycle_duration_hours) / 2500 per cycle under normal conditions.",
      "restored_by": ["filter_cartridge_replacement"],
      "effects_on_fields": ["filter_dp", "filter_f1_state", "inlet_pressure", "w21_filter_clogging_triggered", "a22_filter_blocked_triggered", "active_warning_codes", "active_alarm_codes", "cavitation_detected", "cavitation_risk"]
    },
    {
      "state_variable": "impeller_wear",
      "accumulates_from": "Operating hours at rated conditions. Normal wear rate: 1/20000 per operating hour. Cavitation accelerates wear: rate doubles (1/10000 per hour) when inlet_pressure < 0.5 bar. impeller_wear increments each cycle by (cycle_duration_hours * wear_rate).",
      "restored_by": ["pump_overhaul"],
      "effects_on_fields": ["discharge_pressure", "motor_current", "pump_performance_state", "w31_pump_performance_low_triggered", "a32_pump_worn_triggered", "a33_motor_current_high_triggered", "active_warning_codes", "active_alarm_codes", "pump_p1_state"]
    },
    {
      "state_variable": "cavitation_exposure_hours",
      "accumulates_from": "Hours of operation with inlet_pressure below 0.5 bar. Increments each cycle by the fraction of cycle_duration spent in cavitation conditions.",
      "restored_by": ["filter_cartridge_replacement", "pump_overhaul"],
      "effects_on_fields": ["impeller_wear", "vibration_rms", "cavitation_detected", "cavitation_risk", "w35_vibration_warning_triggered", "a36_vibration_alarm_triggered"]
    },
    {
      "state_variable": "motor_thermal_state",
      "accumulates_from": "Heat generated by motor_current^2 * resistance during the cycle. Rises toward steady-state temperature with a thermal time constant of ~1800 seconds.",
      "restored_by": ["pump_stopped_cooling_period"],
      "effects_on_fields": ["motor_temperature", "a34_motor_temperature_high_triggered", "active_alarm_codes", "pump_p1_state"]
    }
  ],
  "maintenance_model": [
    {
      "event_type": "filter_cartridge_replacement",
      "trigger": "Scheduled every 2000 operating hours, or immediately when a22_filter_blocked_triggered is True. Under high particle load, may trigger as early as 500 operating hours.",
      "effect_on_state": "Resets filter_loading to 0.0 and filter_dp_base to 0.10 bar (clean cartridge baseline). Cavitation_exposure_hours accumulation from filter restriction is halted."
    },
    {
      "event_type": "pump_overhaul",
      "trigger": "Scheduled every 8000 operating hours for inspection; full overhaul when a32_pump_worn_triggered is True with normal filter_dp, or at 20000 operating hours.",
      "effect_on_state": "Resets impeller_wear to 0.0. Discharge pressure at rated flow returns to 4.5 bar. Motor current at rated flow returns to 3.2 A. Vibration_rms baseline returns to ~1.0 mm/s."
    },
    {
      "event_type": "pump_stopped_cooling_period",
      "trigger": "Pump P1 commanded off (pump_p1_running = False) after a fault alarm or scheduled downtime.",
      "effect_on_state": "motor_thermal_state decays exponentially toward ambient temperature with time constant ~1800 seconds. No effect on filter_loading or impeller_wear."
    }
  ],
  "failure_model": [
    {
      "failure_name": "filter_blocked",
      "trigger_conditions": "filter_loading reaches a level where filter_dp exceeds 0.80 bar at rated flow. Typically occurs after 2000-3000 operating hours under normal conditions, or as early as 500 hours under high particle load.",
      "observable_effects": ["filter_dp > 0.80 bar", "filter_f1_state = blocked", "a22_filter_blocked_triggered = True", "inlet_pressure reduced", "cavitation_risk elevated", "active_alarm_codes includes A-22"]
    },
    {
      "failure_name": "pump_worn",
      "trigger_conditions": "impeller_wear reaches a level where discharge_pressure at rated flow falls below 3.5 bar. Occurs at ~20000 operating hours under normal conditions, or ~10000 hours with sustained cavitation.",
      "observable_effects": ["discharge_pressure < 3.5 bar at rated flow", "pump_performance_state = worn", "motor_current elevated above 4.5 A", "a32_pump_worn_triggered = True", "a33_motor_current_high_triggered = True", "active_alarm_codes includes A-32 and A-33", "pump_p1_state = fault"]
    },
    {
      "failure_name": "motor_overtemperature",
      "trigger_conditions": "motor_thermal_state exceeds 95 degC, caused by sustained high motor_current (from impeller wear) combined with long cycle duration or high ambient/water temperature.",
      "observable_effects": ["motor_temperature > 95 degC", "a34_motor_temperature_high_triggered = True", "active_alarm_codes includes A-34", "pump_p1_state = fault"]
    },
    {
      "failure_name": "cavitation_induced_vibration",
      "trigger_conditions": "inlet_pressure drops below 0.5 bar during a cycle, causing pump cavitation. Triggered by heavily clogged filter or low supply pressure.",
      "observable_effects": ["cavitation_detected = True", "cavitation_risk = True", "vibration_rms elevated (potentially > 4.5 or > 7.1 mm/s)", "w35_vibration_warning_triggered = True", "a36_vibration_alarm_triggered may be True", "active_warning_codes includes W-35", "active_alarm_codes may include A-36", "accelerated impeller_wear accumulation"]
    },
    {
      "failure_name": "vibration_alarm",
      "trigger_conditions": "vibration_rms exceeds 7.1 mm/s, caused by cavitation or advanced impeller wear.",
      "observable_effects": ["a36_vibration_alarm_triggered = True", "active_alarm_codes includes A-36", "pump_p1_state = fault", "w35_vibration_warning_triggered = True"]
    }
